// TableStat's cook: a region and its length, and then records in place (§7).
//
// The bytes belong to the CONSUMER — a file it read, or memory a producer
// handed across. Nothing here copies them.
final class TableStatCook {
  final Uint8List bytes;
  final ByteData view;
  // the REGION's first byte within bytes, and the data part's length
  final int region;
  final int length;

  const TableStatCook(this.bytes, this.view, this.region, this.length);

  /// A cursor over this cook's records, to lend to [root] and to the row
  /// accessors that follow a reference.
  TableStatRow cursor() => TableStatRow(view, region);

  /// The ROOT, which sits at offset 0 of the region (§7.1), moved onto the
  /// cursor the caller lends. There is no allocating twin: a walk that
  /// follows references moves one cursor per record type and allocates
  /// nothing per node, and [cursor] makes the one you lend.
  TableStatRow root(TableStatRow into) {
    into.at = region;
    return into;
  }

  // open checks the header and POINTS, and this is the WHOLE check (§7): the
  // magic read bytewise, the byte order it establishes, the build version,
  // every RESERVED word zero, the region ALIGNMENT the header names, the two
  // part lengths against the length the caller passed — a truncated file
  // refuses — the ROOT's own storage inside the data part, and the alignment
  // of the base. Nothing per node, ever: that is what makes this O(1) in the
  // file's size.
  //
  // On a match the bytes ARE what this build wrote, in this build's layout and
  // this build's byte order, so there is nothing to validate and nothing to
  // fix up. On any failure it returns null and points at nothing, and the
  // caller falls back to a wire load — the path that carries every version.
  //
  // EVERY NUMBER BELOW COMES OUT OF THE FILE. Dart's int is signed and 64 bits
  // wide, so a forged word near 2^63 arrives NEGATIVE — and every term is
  // bounded BEFORE it is added, so nothing here wraps past the top of the
  // type and lands back inside the buffer.
  //
  // open is openWithReason without the reason: the same checks in the same
  // order, so the verdict and the reason never disagree.
  static TableStatCook? open(Uint8List? bytes, int at, int length) {
    return openWithReason(bytes, at, length).$1;
  }

  // openWithReason answers the cook and the FIRST failing clause beside the
  // null, as the reference leg names it (docs/SPEC-TABLES.md §7, the clauses in
  // the order internal/codegen/gotable/cook.go's Open checks them): no buffer
  // is an unaligned base, a claim under the header or past the caller's bytes
  // is truncated, the magic is not_a_cook or, read byte-reversed,
  // foreign_order, then the order word, the build version, the reserved words,
  // the alignment word, the two part lengths and the root inside the data
  // part, and last the base's own alignment.
  static (TableStatCook?, TableRefuseReason) openWithReason(
    Uint8List? bytes,
    int at,
    int length,
  ) {
    if (bytes == null || at < 0) {
      return (null, TableRefuseReason.unalignedBase);
    }
    if (length < 64) {
      return (null, TableRefuseReason.truncated);
    }
    if (length > bytes.length - at) {
      // the claim runs past the bytes the caller owns
      return (null, TableRefuseReason.truncated);
    }
    final view = ByteData.view(
      bytes.buffer,
      bytes.offsetInBytes,
      bytes.lengthInBytes,
    );

    // THE MAGIC, read BYTEWISE before anything else: it is what establishes
    // the byte order every other header word is written in. A cook of the
    // other order reads back this constant byte-reversed and refuses HERE,
    // rather than reaching a fix-up pass this design does not have.
    final magic = tableCookRead64(view, at);
    if (magic != tableCookMagic) {
      return (
        null,
        magic == 0x5343484d434f4f4b
            ? TableRefuseReason.foreignOrder
            : TableRefuseReason.notACook,
      );
    }
    // and the ORDER WORD does the other job: it RECORDS which order wrote the
    // file, so a refusal names the order rather than inferring it.
    if (tableCookRead64(view, at + 16) != tableCookByteOrder) {
      return (null, TableRefuseReason.notACook);
    }
    // THE BUILD VERSION: under the match-and-point rule a matching id means
    // open checks nothing further, so it is the sole guard between this
    // runtime and a foreign region (§20).
    if (tableCookRead64(view, at + 8) != tableBuildVersion) {
      return (null, TableRefuseReason.wrongBuildVersion);
    }
    // THE RESERVED WORDS: a non-zero one means a writer used a form this
    // build does not understand, and open refuses rather than ignoring it.
    if (tableCookRead64(view, at + 48) != 0 ||
        tableCookRead64(view, at + 56) != 0) {
      return (null, TableRefuseReason.reservedNotZero);
    }

    // THE ALIGNMENT WORD is the one field the check COMPUTES WITH rather than
    // only compares against — the data part begins at align_up(64, alignment)
    // — so a word that is not an alignment rounds nothing and aligns nothing:
    // at least the floor, at most the ceiling, a power of two, and a multiple
    // of the ROOT's own alignof.
    final alignment = tableCookRead64(view, at + 40);
    if (alignment < 8 ||
        alignment > 64 ||
        alignment & (alignment - 1) != 0 ||
        alignment % 4 != 0) {
      return (null, TableRefuseReason.badAlignment);
    }

    // THE DATA OFFSET IS DERIVED, never a header field: a fact a reader
    // computes is a fact two writers cannot disagree about.
    final dataOffset = (64 + alignment - 1) & ~(alignment - 1);

    // THE TWO PART LENGTHS against the length the caller passed. The whole
    // file is dataOffset + data + attribution, and a size that is not exactly
    // that refuses: a truncated file and a file with trailing bytes are the
    // same refusal. A length past 2^63 arrives negative and is not a length.
    //
    // THE DATA PART MUST HOLD THE ROOT. The part lengths frame the FILE; they
    // do not say the region is at least sizeof(root). Without this a forged
    // short data part describes a root partly outside the file, and a
    // match-and-point reader would hand back storage the caller never gave
    // it — the one way this design could read past the length it was passed.
    final dataLength = tableCookRead64(view, at + 24);
    final attribution = tableCookRead64(view, at + 32);
    if (dataLength < 0 ||
        attribution < 0 ||
        dataOffset > length ||
        dataLength > length - dataOffset ||
        attribution != length - dataOffset - dataLength ||
        dataLength < 8) {
      return (null, TableRefuseReason.truncated);
    }

    // THE ALIGNMENT OF THE BASE, on the offset the caller placed the file at —
    // the only base a Dart consumer holds (§19.1's rule, in this language's
    // currency).
    if (at % alignment != 0) {
      return (null, TableRefuseReason.unalignedBase);
    }

    return (
      TableStatCook(bytes, view, at + dataOffset, dataLength),
      TableRefuseReason.ok,
    );
  }

  // A REFERENCE IS DEREFERENCED THROUGH at, and it is the same encoding in a
  // locked region and an opened cook (§6.3): the slot is eight bytes, SIGNED,
  // self-relative from the SLOT'S OWN position, so a deref is one add and
  // NULL IS A DELTA OF ZERO.
  //
  // It takes the SLOT's offset and not its value, because a self-relative
  // delta means nothing without the position it is relative to. The size is
  // the pointee record's full extent, bounded before any target addition.
  // The slot itself must hold eight bytes inside the region. It answers
  // the TARGET's offset, TableCookRef.none for a null, and
  // TableCookRef.outside for a slot or target record outside the region — C++
  // need not check and Dart does, because the read after it would be an
  // escaping RangeError rather than a refusal.
  int at(int slot, int size) {
    if (size < 0 || length < 8 || slot < region || slot - region > length - 8) {
      return TableCookRef.outside;
    }
    final delta = view.getInt64(slot, Endian.little);
    if (delta == 0) {
      return TableCookRef.none;
    }
    final relative = slot - region;
    // Bound the delta before addition: the entire record must fit (§7).
    if (delta < -relative || delta > length - size - relative) {
      return TableCookRef.outside;
    }
    return slot + delta;
  }

  // this root's cook descriptors: CONSTANT data, so a reflective walk costs a
  // lookup and not a parse. Every record the region can hold hangs off the
  // field column, so a walker reaches the whole graph from the root — and
  // they are MEMBERS, so the graph claims one name and that name is the
  // root's (docs/SPEC-TABLES.md §11).
  static const TableCookInfo type = TableCookInfo(
    name: 'TableStat',
    size: 8,
    align: 4,
    fields: <TableCookFieldInfo>[
      TableCookFieldInfo(
        name: 'stat_id',
        offset: 0,
        size: 4,
        elemSize: 4,
        isArray: false,
        arrayBound: 1,
        isPointer: false,
        countOffset: -1,
        presentOffset: -1,
        storage: TableCookStorage.unsigned,
        record: null,
      ),
      TableCookFieldInfo(
        name: 'delta',
        offset: 4,
        size: 4,
        elemSize: 4,
        isArray: false,
        arrayBound: 1,
        isPointer: false,
        countOffset: -1,
        presentOffset: -1,
        storage: TableCookStorage.signed,
        record: null,
      ),
    ],
  );
  // The fixed cook's extent is constant; every storage slot is written (§7.6).
  static int cookMeasure(TableStat value) => 88;

  // Capacity and value validation precede every output write (§7.6).
  static bool cook(
    TableStat value,
    Uint8List output,
    Endian order, {
    TableCookWriteReport? report,
  }) {
    if (report != null) report.reason = 'ok';
    if ((order != Endian.little && order != Endian.big) ||
        output.length < 88 ||
        !_cookTableStat(value, null, 64, order)) {
      if (report != null) report.reason = 'invalid_value';
      return false;
    }
    output.fillRange(0, 88, 0);
    final view = ByteData.sublistView(output);
    view.setUint64(0, tableCookMagic, order);
    view.setUint64(8, tableBuildVersion, order);
    view.setUint64(16, order == Endian.little ? 1 : 2, order);
    view.setUint64(24, 8, order);
    view.setUint64(32, 16, order);
    view.setUint64(40, 8, order);
    view.setUint64(72, 0, order);
    view.setUint64(80, 2984383410656091285, order);
    return _cookTableStat(value, view, 64, order);
  }

  // The shared ABI's field pieces, not the fixed wire's packed widths (§7.2).
  static bool _cookTableStat(
    TableStat value,
    ByteData? out,
    int at,
    Endian order,
  ) {
    if (out != null) {
      out.setUint32(at + 0, value.statId, order);
    }
    if (out != null) {
      out.setInt32(at + 4, value.delta, order);
    }
    return true;
  }
}

